    private boolean invals(Object value, Object... valueList) {
        if ((value == null) || (valueList == null)) {
            return false;
        }
        for (int i = 0; i < valueList.length; i++) {
            if (valueList[i] != null) {
                if (value.toString().equalsIgnoreCase(valueList[i].toString())) {
                    return true;
                }
            }
        }
        return false;
    }

